    benefits: [{"title": "Practical Skills", "body": "CBT teaches concrete tools you can use on your own, long after treatment ends."}, {"title": "Structured and Focused", "body": "Work stays centered on specific goals, so you can see what is changing and why."}, {"title": "Well Researched", "body": "CBT is one of the most widely studied therapies for depression, anxiety and related concerns."}, {"title": "Integrated Psychiatric Perspective", "body": "Therapy can be considered alongside a broader view of your mental health, including medication when appropriate."}],
